def solve2(w, c0):
    H = w
    g = [[0]*H for _ in range(H)]
    for r in range(H):
        for c in (c0-r, c0+r):
            if 0 <= c < H:
                g[r][c] = 2
    # global lattice: down-right lines k = c - r ≡ 2 (mod 4)
    ks = [k for k in range(-H, H) if k % 4 == 2]
    for k in ks:
        cross = (c0 + k) / 2  # row where line crosses left arm c = c0 - r
        start = max(int(cross)+1 if cross == int(cross) else 0, k if k > 0 else 0, 0)
        for r in range(start, H):
            c = r - k
            if 0 <= c < H and g[r][c] == 0:
                g[r][c] = 1
    return g

