def solve3(w, c0):
    H = w
    g = [[0]*H for _ in range(H)]
    for r in range(H):
        for c in (c0-r, c0+r):
            if 0 <= c < H:
                g[r][c] = 2
    for k in range(1-H, H):
        if k % 4 != 2: continue
        cross = (c0 + k) / 2
        if cross < 0 or cross != int(cross): continue
        start = max(int(cross)+1, max(k, 0))
        for r in range(start, H):
            c = r - k
            if 0 <= c < H and g[r][c] == 0:
                g[r][c] = 1
    return g

